def dif_Square(n: int) -> bool:
    if n == 0:
        return True
    abs_n = abs(n)
    # Iterate over all possible divisors including negative ones to cover parity with negative factors
    # but to avoid redundancy, we can iterate over positive divisors and check both signs for factors.
    # Because parity depends only on integers, considering positive divisors and pairing with n//d is sufficient.
    for d in range(1, int(abs_n**0.5) + 1):
        if abs_n % d == 0:
            x_candidates = [(d, n // d), (-d, -n // d)]
            for x, y in x_candidates:
                # Check parity: both even or both odd
                if (x % 2) == (y % 2):
                    # a = (x + y) / 2, b = (y - x) / 2 are integers
                    # no need to explicitly compute a,b, parity condition ensures integrality
                    return True
    return False



