def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If num is all 9s, the next palindrome is 10...01 (length+1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    # Start by creating palindrome from left half
    half_len = (length + 1) // 2
    left_part = s[:half_len]

    palindrome = make_palindrome(left_part, length % 2 == 1)

    if palindrome > num:
        return palindrome

    # Increment the left part and generate palindrome again
    # Handle the carry if incrementing left_part overflows
    left_int = int(left_part) + 1
    left_str = str(left_int)
    # If length changes after increment, means palindrome length increases
    if len(left_str) > len(left_part):
        # For example 999 + 1 = 1000, so next palindrome is 10...01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')
    else:
        return make_palindrome(left_str, length % 2 == 1)



