def find_solution(a: int, b: int, n: int):
    # Handle the case b == 0 separately
    if b == 0:
        # Equation: a*x = n
        # x must be non-negative integer and y can be any integer (but must be non-negative)
        # So y must be non-negative integer as well (0 or more)
        # So if b=0, we want y >= 0 integer, and equation is a*x + 0*y = n -> a*x = n
        # So x = n / a if a != 0 and x >=0 integer, y can be 0 (since y>=0)
        # If a == 0, then equation is 0*x + 0*y = n, so only n==0 works with x,y >=0
        if a == 0:
            if n == 0:
                return (0, 0)
            else:
                return "No solution"
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return "No solution"

    # If b != 0, iterate x from 0 upwards
    # We cannot iterate infinitely, so set a reasonable bound:
    # Since y = (n - a*x)/b must be integer and y >= 0,
    # (n - a*x)/b >= 0
    # So n - a*x and b must have same sign or zero
    # We'll iterate x from 0 to some upper bound
    # Upper bound can be found by constraints on y:
    # y >= 0 => (n - a*x)/b >= 0 => (n - a*x)*b >= 0

    # Because a and b can be any integer (including zero), we must be careful.

    # We try x starting at 0, stop when no further solutions possible:
    # Let's define search bounds:
    # Since x >= 0, we will search upward until (n - a*x)*b < 0 (no y >= 0 possible beyond)
    # But if a=0, then y = n/b must be integer and >=0, x=0 is the only candidate.

    # To avoid infinite loop, we proceed until (n - a*x)*b < 0 for increasing x (if b>0)
    # or (n - a*x)*b < 0 for increasing x (if b<0)

    # Also, if a=0, then x=0 only candidate.

    # So let's implement accordingly:

    x = 0
    # Flag to stop search when no solution possible further
    while True:
        numerator = n - a * x
        # Check if numerator divisible by b
        if numerator % b == 0:
            y = numerator // b
            if y >= 0:
                return (x, y)
        # Check if further increasing x can yield y >= 0
        # Condition for y >= 0 is (n - a*x)*b >= 0
        # If this condition fails, break
        if (numerator * b) < 0:
            break
        x += 1
        # To prevent infinite loop in cases where no solution and no stopping condition,
        # we impose a search limit:
        # Since a,b,n can be zero, we set a large arbitrary limit
        if x > 10**7:
            break

    return "No solution"



