def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 0:
        return 1
    dp = [1] * (m + 1)
    for _ in range(2, n + 1):
        prefix_sums = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix_sums[x] = prefix_sums[x - 1] + dp[x]
        new_dp = [0] * (m + 1)
        for x in range(1, m + 1):
            lower = 2 * x
            if lower <= m:
                new_dp[x] = prefix_sums[m] - prefix_sums[lower - 1]
            else:
                new_dp[x] = 0
        dp = new_dp
    return sum(dp[1:])



