from typing import List

def find_Max(array: List[int], start: int, end: int) -> int:
    if start == end:
        return array[start]
    left, right = start, end
    while left < right:
        mid = (left + right) // 2
        if array[mid] > array[right]:
            left = mid + 1
        else:
            right = mid
    min_idx = left
    max_idx = min_idx - 1 if min_idx > start else end
    # Check for strictly descending subarray, max may be at start if rotation point is start
    # Because in descending order max is at start
    # Confirm max by comparing with start element
    if array[start] > array[max_idx]:
        return array[start]
    return array[max_idx]



