def capital_words_spaces(s: str) -> str:
    def is_word_char(c: str) -> bool:
        return c.isascii() and (c.isalpha() or c.isdigit() or c == '_')

    res = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if 'A' <= c <= 'Z':
            # start of a capital sequence
            start = i
            while i < n and 'A' <= s[i] <= 'Z':
                i += 1
            seq = s[start:i]
            # check preceding char
            if start == 0:
                # at start, no space
                res.append(seq)
            else:
                prev = s[start-1]
                if is_word_char(prev):
                    res.append(' ' + seq)
                else:
                    res.append(seq)
        else:
            res.append(c)
            i += 1
    return ''.join(res)



