def lucky_num(n: int) -> list[int]:
    # Start with odd numbers from 1 upwards, enough to generate n lucky numbers after sieving
    # We pick a generous initial range to ensure enough numbers remain after sieving
    size = max(2 * n * n, 10)
    numbers = list(range(1, 2 * size, 2))  # odd numbers starting at 1

    idx = 1  # start sieve step from the second element (index 1), since first is 1
    while idx < len(numbers) and len(numbers) < n:
        # In case list is still too short, extend it
        extra_size = size
        last = numbers[-1]
        numbers.extend(range(last + 2, last + 2 * extra_size, 2))
        size += extra_size

    while True:
        if idx >= len(numbers):
            # Extend list if needed to ensure enough numbers to sieve
            extra_size = size
            last = numbers[-1]
            numbers.extend(range(last + 2, last + 2 * extra_size, 2))
            size += extra_size
        step = numbers[idx]
        if step > len(numbers):
            # If step is larger than current list length, no more sieving possible
            break
        # Remove every step-th number (1-based indexing)
        # Positions to remove: step-1, 2*step-1, 3*step-1, ...
        # Build new list including only elements not at these positions
        new_numbers = []
        for i, num in enumerate(numbers):
            if (i + 1) % step != 0:
                new_numbers.append(num)
        numbers = new_numbers
        idx += 1
        if len(numbers) >= n:
            break

    return numbers[:n]



