def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)
    if all(ch == '9' for ch in s):
        # If all 9's, next palindrome is 10..01 (length+1)
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_len: bool) -> int:
        # Construct palindrome by mirroring left part
        if odd_len:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    half_len = (length + 1) // 2
    left = s[:half_len]
    odd_len = (length % 2 != 0)
    pal = make_palindrome(left, odd_len)

    if pal > num:
        return pal

    # Increment left part and form palindrome again
    left_num = int(left) + 1
    left_str = str(left_num)
    # If increment causes length increase (e.g. 999 -> 1000)
    if len(left_str) > len(left):
        # This means palindrome length increases by 1
        # So return 10...01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')
    else:
        return make_palindrome(left_str, odd_len)



