def find_solution(a, b, n):
    from math import gcd

    def extended_gcd(aa, bb):
        if bb == 0:
            return aa, 1, 0
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return g, x, y

    # Handle trivial cases where both a and b are zero
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else "No solution"

    # Handle cases where one coefficient is zero
    if a == 0:
        if b == 0:
            return "No solution"
        if n % b == 0:
            return (0, n // b)
        else:
            return "No solution"
    if b == 0:
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
            else:
                return "No solution"
        else:
            return "No solution"

    g = gcd(a, b)
    if n % g != 0:
        return "No solution"

    a_div, b_div, n_div = a // g, b // g, n // g
    g2, x0, y0 = extended_gcd(abs(a_div), abs(b_div))
    # Adjust signs for x0, y0 based on signs of a_div, b_div
    if a_div < 0:
        x0 = -x0
    if b_div < 0:
        y0 = -y0

    x0 *= n_div
    y0 *= n_div

    # General solution: x = x0 + k*(b_div), y = y0 - k*(a_div)
    # We want smallest x >= 0

    # If b_div == 0 (should be handled above), no step possible
    if b_div == 0:
        if x0 >= 0:
            return (x0, y0)
        else:
            return "No solution"

    # Find k such that x = x0 + k*b_div >= 0 and minimal
    # If b_div > 0: k >= ceil(-x0 / b_div)
    # If b_div < 0: k <= floor(-x0 / b_div)

    if b_div > 0:
        k = (-x0 + b_div - 1) // b_div  # ceil division
    else:
        k = (-x0) // b_div  # floor division since b_div < 0

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0:
        return "No solution"
    return (x, y)



