def get_total_number_of_sequences(N: int, K: int) -> int:
    if K == 1:
        return N

    # dp[i][x]: number of sequences of length i ending with x
    # Only keep dp for previous length to save memory
    prev_dp = [0] * (N + 1)
    for x in range(1, N + 1):
        prev_dp[x] = 1

    for length in range(2, K + 1):
        curr_dp = [0] * (N + 1)
        # prefix sums for prev_dp
        prefix = [0] * (N + 2)
        for x in range(1, N + 1):
            prefix[x] = prefix[x - 1] + prev_dp[x]

        for x in range(1, N + 1):
            start = 2 * x
            if start <= N:
                curr_dp[x] = prefix[N] - prefix[start - 1]
            else:
                curr_dp[x] = 0
        prev_dp = curr_dp

    return sum(prev_dp[1:])



