import re

def text_match_two_three(s: str) -> bool:
    """
    Check if the input string contains the pattern of a lowercase 'a' followed immediately by 
    exactly 2 or 3 lowercase 'b's anywhere within it.

    The matching is case-sensitive: only the exact sequence 'abb' or 'abbb' counts as a match.

    Parameters:
    s (str): The input string to search.

    Returns:
    bool: True if the pattern 'abb' or 'abbb' occurs anywhere in the string; False otherwise.

    Examples:
    >>> text_match_two_three("aabb")
    False
    >>> text_match_two_three("abbc")
    True
    >>> text_match_two_three("abbbd")
    True
    >>> text_match_two_three("aBB")
    False
    >>> text_match_two_three("aabbb")
    True
    """
    # The pattern should match exactly 'abb' or 'abbb' substrings, no more b's in sequence.
    # Use negative lookahead to ensure no 4th 'b' follows.
    return bool(re.search(r'ab{2,3}(?!b)', s))



