def remove_column(collection, pos):
    if not isinstance(collection, list):
        return collection
    result = []
    for item in collection:
        if isinstance(item, list):
            # Remove element at pos if possible
            new_item = item[:]  # shallow copy
            if 0 <= pos < len(new_item):
                del new_item[pos]
            # Recurse into each element of new_item
            new_item = [remove_column(subitem, pos) for subitem in new_item]
            result.append(new_item)
        else:
            result.append(item)
    return result



