def str_to_tuple(input_str, output_format):
    import ast

    # Wrap input_str in brackets if top-level grouping absent (to parse as list)
    s = input_str.strip()
    # Detect if input_str is a single integer without any comma or brackets
    if s and s[0] != '[' and ',' not in s:
        # Single integer string like "42"
        parsed = int(s)
    else:
        # To parse multiple groups or single group, wrap in brackets if not already top-level list
        # Check if top-level is a single group without surrounding brackets
        # If input is like "1,2,3" or "[1,2],[3,4]" or "42"
        # We can parse as a tuple/list if we wrap it as a list: "[" + input_str + "]"
        # But if input_str is already a single bracketed group with no outer brackets, e.g. "[1,2]"
        # wrapping again is safe.
        try:
            parsed = ast.literal_eval(input_str)
        except (SyntaxError, ValueError):
            # Fallback wrap and parse
            parsed = ast.literal_eval(f"[{input_str}]")

    # If parsed is int (single integer), normalize to a sequence for output_format 'tuple' or 'list'
    def normalize_structure(obj):
        if isinstance(obj, int):
            return obj
        elif isinstance(obj, (list, tuple)):
            return type(obj)(normalize_structure(x) for x in obj)
        else:
            # Should not occur given input assumptions
            return obj

    # If input was a single integer parse result, wrap to tuple or list accordingly
    if isinstance(parsed, int):
        if output_format == "string":
            return str(parsed)
        elif output_format == "tuple":
            return (parsed,)
        elif output_format == "list":
            return [parsed]

    # For output_format string, flatten all digits ignoring grouping and commas
    if output_format == "string":
        # Extract all digit characters from input_str in order
        digits = ''.join(ch for ch in input_str if ch.isdigit())
        return digits

    # For tuple or list output, convert all lists/tuples in parsed to desired type recursively
    def convert_structure(obj):
        if isinstance(obj, int):
            return obj
        elif isinstance(obj, (list, tuple)):
            converted = [convert_structure(x) for x in obj]
            if output_format == "tuple":
                return tuple(converted)
            else:  # output_format == "list"
                return converted
        else:
            # Should not occur given input assumptions
            return obj

    return convert_structure(parsed)



