import re

def capital_words_spaces(text: str, pattern: str) -> str:
    if pattern == '':
        return text  # Undefined behavior for empty pattern, return text unchanged

    pat_esc = re.escape(pattern)
    # Find all non-overlapping occurrences of pattern
    matches = list(re.finditer(pat_esc, text))
    if not matches:
        return text

    result = []
    last_index = 0
    for i, m in enumerate(matches):
        start, end = m.start(), m.end()

        # Append text before this match unchanged
        result.append(text[last_index:start])

        # Determine spaces before pattern occurrence
        # Scan backwards from start to collapse any spaces before pattern
        # But only collapse spaces immediately adjacent to pattern
        pre_start = start
        while pre_start > 0 and text[pre_start - 1] == ' ':
            pre_start -= 1
        # Determine if space before needed:
        # If pattern at start of string, no space before
        # Else exactly one space before pattern
        before_space = ''
        if start > 0:
            before_space = ' '

        # Determine spaces after pattern occurrence
        # Scan forwards from end to collapse any spaces after pattern
        post_end = end
        while post_end < len(text) and text[post_end] == ' ':
            post_end += 1
        # If pattern at end of string, no space after
        # Else exactly one space after pattern
        after_space = ''
        if end < len(text):
            after_space = ' '

        # Append before_space + pattern + after_space
        result.append(before_space + pattern + after_space)

        last_index = post_end

    # Append remaining text after last match unchanged
    result.append(text[last_index:])

    return ''.join(result)



