def Odd_Length_Sum(group):
    """
    Given a list of numbers `group`, return the sum of the sums of all contiguous sublists of `group` whose length is odd.

    Parameters:
    - group (list of numbers): The input list containing numeric elements (integers, floats, etc.).

    Returns:
    - A number representing the total sum of all elements from every contiguous sublist of `group` that has an odd length.

    Notes:
    - The function considers all contiguous slices of `group` with odd lengths (1, 3, 5, ...).
    - Numeric type and precision are preserved according to Python's default arithmetic behavior.

    Examples:
    >>> Odd_Length_Sum([1, 4, 2, 5, 3])
    58
    >>> Odd_Length_Sum([10, 11, 12])
    66
    >>> Odd_Length_Sum([1.5, 2.5])
    4.0
    """
    n = len(group)
    total = 0
    for length in range(1, n + 1, 2):  # odd lengths only
        for start in range(n - length + 1):
            total += sum(group[start:start + length])
    return total



