def lucky_num(n: int) -> list[int]:
    if n == 0:
        return []
    # Start with odd numbers beginning at 1, generate enough to cover n lucky numbers after filtering
    # Start with a reasonable guess of range; if not enough, extend.
    # The density of lucky numbers is roughly ~n * 2 (heuristic), so start with 3*n*2
    limit = max(3 * n * 2, 10)
    while True:
        nums = list(range(1, limit*2, 2))
        idx = 1  # start from the second number (index 1)
        while idx < len(nums):
            step = nums[idx]
            if step > len(nums):
                break
            # Remove every step-th element (1-based), so keep elements where (pos+1) % step != 0
            nums = [x for i, x in enumerate(nums) if (i + 1) % step != 0]
            idx += 1
        if len(nums) >= n:
            return nums[:n]
        limit *= 2



