def dif_Square(n: int) -> bool:
    if n == 0:
        return True
    # n = a^2 - b^2 = (a-b)(a+b) = x*y
    # For integers a,b, both (a-b) and (a+b) must be integers
    # and (a+b + a-b) = 2a and (a+b - (a-b)) = 2b must be even
    # So x and y have same parity
    # For n = x*y, check if there exist x,y integers with same parity and x*y=n
    abs_n = abs(n)
    for x in range(1, int(abs_n**0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # check pairs (x,y) and (-x,-y) if n negative
            for (X, Y) in [(x, y), (y, x)]:
                if n > 0:
                    # x and y must have same parity
                    if (X % 2) == (Y % 2):
                        return True
                else:
                    # for negative n, check if product is -n,
                    # so one factor negative
                    if (X % 2) == (Y % 2):
                        return True
    return False



