def next_smallest_palindrome(n: int) -> int:
    s = str(n + 1)
    length = len(s)
    half = (length + 1) // 2

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    while True:
        left = s[:half]
        palindrome = make_palindrome(left, length % 2 == 1)
        if palindrome > n:
            return palindrome
        # Increment the left half and handle overflow
        left_num = int(left) + 1
        left_str = str(left_num)
        if len(left_str) > len(left):
            # This happens if incrementing left adds a digit (e.g., 999 + 1 = 1000)
            length += 1
            half = (length + 1) // 2
            s = '1' + ('0' * (length - 1))
        else:
            s = left_str + s[half:]



