from typing import Optional, Tuple

def find_solution(a: int, b: int, n: int) -> Optional[Tuple[int, int]]:
    if n < 0:
        return None
    # Handle trivial case
    if n == 0:
        return (0, 0)
    # Handle cases when a or b is zero
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if b != 0 and n % b == 0 and n >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if a != 0 and n % a == 0 and n >= 0:
            return (n // a, 0)
        else:
            return None
    # Both a and b nonzero
    # Try all possible x from 0 to n//a
    max_x = n // a
    for x in range(max_x + 1):
        remainder = n - a * x
        if remainder < 0:
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
    return None



