def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 1:
        return m
    dp_prev = [1] * (m + 1)  # dp_prev[x] = count of sequences of length 1 ending with x, x in [1..m]
    for _ in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        for x in range(1, m + 1):
            c = dp_prev[x]
            if c == 0:
                continue
            dp_curr[x] += c
            double_x = 2 * x
            if double_x <= m:
                dp_curr[double_x] += c
        dp_prev = dp_curr
    return sum(dp_prev[1:])



