def dict_depth(d):
    if not isinstance(d, dict):
        raise TypeError("Input must be a dictionary")
    def helper(obj):
        if isinstance(obj, dict):
            if not obj:
                return 1
            return 1 + max(helper(v) for v in obj.values())
        elif isinstance(obj, (list, tuple)):
            max_depth = 0
            for item in obj:
                if isinstance(item, dict) or isinstance(item, (list, tuple)):
                    max_depth = max(max_depth, helper(item))
            return max_depth
        else:
            return 0
    return helper(d)



