def add_string(elements, fmt):
    # Count substitution slots: empty '{}' and numbered placeholders '{0}', '{1}', etc.
    count = 0
    i = 0
    length = len(fmt)
    while i < length:
        if fmt[i] == '{':
            if i + 1 < length and fmt[i + 1] == '{':
                # Escaped brace '{{', skip both
                i += 2
                continue
            # Find closing brace
            end = fmt.find('}', i + 1)
            if end == -1:
                # No closing brace, malformed but treat as no slot
                i += 1
                continue
            # Extract placeholder content
            content = fmt[i + 1:end].strip()
            # Check if empty or numeric index
            if content == '' or content.isdigit():
                count += 1
            # Move past this placeholder
            i = end + 1
        elif fmt[i] == '}':
            if i + 1 < length and fmt[i + 1] == '}':
                # Escaped brace '}}', skip both
                i += 2
            else:
                # Unescaped '}', skip
                i += 1
        else:
            i += 1

    if count == 1:
        return [fmt.format(e) for e in elements]
    else:
        # No substitution slots or more than one (out of domain)
        return [fmt]



