def find_Max(arr, start, end):
    # If subarray is sorted (no rotation inside), max is at end
    if arr[start] < arr[end]:
        return arr[end]
    # Otherwise, find max by binary search
    left, right = start, end
    while left < right:
        mid = (left + right) // 2
        if arr[mid] > arr[right]:
            left = mid + 1
        else:
            right = mid
    # left is pivot (smallest element), max is element before pivot
    max_index = left - 1 if left > start else end
    return arr[max_index]



