def capital_words_spaces(text: str) -> str:
    """
    Insert spaces before capital letters in the input string to separate words starting with capitals,
    while preserving existing spaces without adding extra spaces.

    Specifically:
    - For each capital letter that directly follows a non-space character (which is not already a space),
      insert a single space before it.
    - Existing spaces in the input string are preserved as-is.
    - The function treats the input as a sequence of words possibly concatenated without spaces before capitals,
      and inserts spaces only where needed to separate capitalized words.

    Examples:
    >>> capital_words_spaces("HelloWorld")
    'Hello World'
    >>> capital_words_spaces("Hello WorldTest")
    'Hello World Test'
    >>> capital_words_spaces("ThisIs ATest")
    'This Is A Test'
    """
    import re
    # Insert a space before any capital letter that is preceded by a non-space character,
    # but do not insert space at the start of the string.
    # Use a lookbehind for a non-space character.
    return re.sub(r'(?<=\S)([A-Z])', r' \1', text)



