def dif_Square(n: int) -> bool:
    """
    Determine whether the integer n can be expressed as the difference of two squares,
    i.e., whether there exist integers a and b such that n = a² - b².

    The function accepts any integer n (positive, zero, or negative) and returns True
    if such integers a and b exist, and False otherwise.

    Examples:
    dif_Square(0)   -> True   # 0 = 0² - 0²
    dif_Square(1)   -> True   # 1 = 1² - 0²
    dif_Square(3)   -> False  # no such representation
    dif_Square(-1)  -> True   # -1 = 0² - 1²
    dif_Square(15)  -> True   # 15 = 4² - 1²

    """
    # Difference of squares: n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b, y = a+b, then n = x*y
    # a = (x+y)/2, b = (y - x)/2 must be integers
    # So x and y must be both even or both odd (same parity)
    # Check if n can be factored into two integers with same parity

    if n == 0:
        return True  # 0 = 0^2 - 0^2

    abs_n = abs(n)
    # To find factors of abs_n and check parity
    # Iterate only up to sqrt(abs_n)
    import math
    limit = int(math.isqrt(abs_n))
    for x in range(1, limit + 1):
