def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)
    if set(s) == {'9'}:
        # all 9s case: next palindrome is 10..01 with length+1
        return int('1' + '0'*(length-1) + '1')

    def make_palindrome(left: str, odd: bool) -> int:
        if odd:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    odd_len = (length % 2 != 0)
    mid = (length // 2)
    if odd_len:
        left = s[:mid+1]
    else:
        left = s[:mid]

    palindrome = make_palindrome(left, odd_len)
    if palindrome > num:
        return palindrome

    # increment the middle part
    if odd_len:
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        if len(left) > (mid+1):  # overflow, e.g. 999 + 1 = 1000
            # length increases, so next palindrome is 10..01 with length+1
            return int('1' + '0'*(length-1) + '1')
        palindrome = make_palindrome(left, odd_len)
        return palindrome
    else:
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        if len(left) > mid:
            return int('1' + '0'*(length-1) + '1')
        palindrome = make_palindrome(left, odd_len)
        return palindrome



