def find_solution(a: int, b: int, n: int) -> tuple[int, int] | str:
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return "No solution"
    if b == 0:
        # Equation reduces to a*x = n
        # Find non-negative x with no y needed (y=0)
        if a == 0:
            return "No solution"
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return "No solution"
    # b != 0 case
    # We scan x from 0 upwards until no solution found or we find one
    # To avoid infinite loops, note that if a and b are both positive,
    # x must be at most n//a if a>0, or we can scan up to some large limit
    # But specification does not limit x, so we scan until solution or no solution.
    # To be safe, we scan up to a large number (e.g. max search range)
    # However, problem wants scanning from 0 upwards indefinitely, but we cannot do infinite loop.
    # Instead, we can scan up to abs(n)*abs(b) + 1 as a safe upper bound.
    # But if a or b is zero or negative, we need to handle accordingly.

    # We can do an unbounded search but must be careful.
    # Instead, use a search bound:
    # Since ax + by = n
    # For x >= 0, y = (n - a*x)/b
    # y integer means (n - a*x) divisible by b
    # We scan x from 0 until y is integer and return first found.
    # We stop if x exceeds a reasonable bound where y can no longer be integer or x becomes too large.
    # Since no domain restrictions, scan x from 0 up to abs(n)*abs(b)+1

    limit = abs(n)*abs(b) + 1 if n != 0 else 1000
    for x in range(limit):
        rem = n - a * x
        if rem % b == 0:
            y = rem // b
            return (x, y)
    return "No solution"



