def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 1:
        return m if m >= 1 else 0
    if m < 1 or n < 1:
        return 0
    # dp[i][x]: number of sequences of length i ending with x
    dp_prev = [1] * (m + 1)  # for i=1, sequences of length 1 ending at x is 1 for x in [1..m]
    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        # To speed up summation, we use prefix sums of dp_prev
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp_prev[x]
        for x in range(1, m + 1):
            start = 2 * x
            if start > m:
                dp_curr[x] = 0
            else:
                # sum dp_prev[y] for y in [start..m] = prefix[m] - prefix[start-1]
                dp_curr[x] = prefix[m] - prefix[start - 1]
        dp_prev = dp_curr
    return sum(dp_prev[1:])



