def remove_column(data, index):
    result = []
    for inner in data:
        length = len(inner)
        # Calculate adjusted index for negative values
        adjusted_index = index if index >= 0 else length + index
        if 0 <= adjusted_index < length:
            # Remove the element at adjusted_index
            new_inner = inner[:adjusted_index] + inner[adjusted_index + 1 :]
