def smallest_missing(array, left, right):
    if left > right:
        return 0
    length = right - left + 1
    # Partition the subarray so that all values in [0, length-1] are moved to the front if present
    i = left
    while i <= right:
        val = array[i]
        # Check if val is in range and not at its correct position
        while 0 <= val < length and array[left + val] != val:
            target_idx = left + val
            array[i], array[target_idx] = array[target_idx], array[i]
            val = array[i]
        i += 1
    # Find the first index in [0..length-1] where value is not equal to index
    for i in range(length):
        if array[left + i] != i:
            return i
    return length



