from collections import Counter

def permute_string(s: str) -> list[str]:
    if s == "":
        return [""]
    counter = Counter(s)
    result = []
    path = []
    length = len(s)

    def backtrack():
        if len(path) == length:
            result.append("".join(path))
            return
        for char in sorted(counter):
            if counter[char] > 0:
                path.append(char)
                counter[char] -= 1
                backtrack()
                counter[char] += 1
                path.pop()

    backtrack()
    return result



