def capital_words_spaces(s: str) -> str:
    if not s:
        return s
    result = [s[0]]
    i = 1
    length = len(s)
    while i < length:
        c = s[i]
        if c.isupper():
            # Check if previous char is not uppercase to insert space
            if not s[i-1].isupper():
                result.append(' ')
            # Append all consecutive uppercase letters as a group
            while i < length and s[i].isupper():
                result.append(s[i])
                i += 1
            continue
        else:
            result.append(c)
            i += 1
    return ''.join(result)



