def lucky_num(n: int) -> list[int]:
    if n == 0:
        return []
    # Start with all positive odd numbers (since lucky numbers are odd except 1)
    # but we must include 1 as the first lucky number
    # We do not know how far to go, so use a dynamic approach
    # initial list: all odd numbers starting from 1, enough to find n lucky numbers
    size = n * 20
    nums = list(range(1, size * 2, 2))
    idx = 1
    while idx < len(nums):
        step = nums[idx]
        if step > len(nums):
            break
        # Remove every step-th number starting from index step-1
        del nums[step - 1::step]
        idx += 1
        # If we have enough lucky numbers, stop
        if len(nums) >= n:
            continue
        # Otherwise, extend the list with next odd numbers
        last = nums[-1]
        # next odd number after last
        start = last + 2
        nums.extend(range(start, start + (n * 10) * 2, 2))
    return nums[:n]



