def dif_Square(n: int) -> bool:
    if n < 0:
        return False
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b >= 0, y = a+b >= x, both integers, and x,y have same parity.
    # Then n = x*y, x,y >= 0, y >= x, y-x even.
    # So check if n can be factored into x*y with x,y >=0, same parity, y>=x, and x*y=n.
    # x=0 => n=0*y=0; zero case allowed.
    # Iterate x from 0 to int(sqrt(n)) and check conditions.
    from math import isqrt
    for x in range(isqrt(n) + 1):
        if x == 0:
            if n == 0:
                return True
            continue
        if n % x != 0:
            continue
        y = n // x
        if y < x:
            continue
        if (y - x) % 2 == 0:
            return True
    return False



