def next_smallest_palindrome(n: int) -> int:
    if n <= 0:
        # No palindrome strictly less than n if n <= 0, return -1 as convention
        # Spec does not clarify domain; returning -1 to indicate no valid palindrome
        return -1
    # Helper to check palindrome
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    # If n is single digit > 0, next smallest palindrome is n-1 if n>0
    if n <= 10:
        return n - 1

    s = str(n)
    length = len(s)

    # Generate palindrome from left half
    def make_palindrome(left: str, odd_len: bool) -> int:
        if odd_len:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    odd_len = (length % 2 != 0)
    left_len = (length + 1) // 2
    left = s[:left_len]
    pal = make_palindrome(left, odd_len)

    if pal >= n:
        # Need to decrement the left half and form palindrome again
        left_num = int(left) - 1
        # If left_num is zero or less, this means palindrome with fewer digits
        if left_num <= 0:
            # Return the largest palindrome with fewer digits: all 9's
            return int('9' * (length - 1)) if length > 1 else 0
        left_str = str(left_num)
        # Pad left_str with zeros if needed
        left_str = left_str.zfill(left_len)
        pal = make_palindrome(left_str, odd_len)
        if pal >= n:
            # If still >= n, decrement again until palindrome < n
            while pal >= n and left_num > 0:
                left_num -= 1
                if left_num <= 0:
                    return int('9' * (length - 1)) if length > 1 else 0
                left_str = str(left_num).zfill(left_len)
                pal = make_palindrome(left_str, odd_len)
        return pal
    else:
        return pal



