def find_solution(a: int, b: int, n: int):
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, x1, y1 = extended_gcd(y, x % y)
        return (g, y1, x1 - (x // y) * y1)

    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        return None

    x0 *= n // g
    y0 *= n // g

    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return (x0, y0)



