def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 1:
        return m
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1
    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        suffix_sum = [0] * (m + 2)  # suffix_sum[i] = sum of dp[i..m]
        for i in range(m, 0, -1):
            suffix_sum[i] = suffix_sum[i + 1] + dp[i]
        for x in range(1, m + 1):
            low = 2 * x
            if low <= m:
                new_dp[x] = suffix_sum[low]
            else:
                new_dp[x] = 0
        dp = new_dp
    return sum(dp[1:m+1])



