def dict_depth(d: dict) -> int:
    if not d:
        return 1
    max_subdepth = 0
    for v in d.values():
        if isinstance(v, dict):
            subdepth = dict_depth(v)
            if subdepth > max_subdepth:
                max_subdepth = subdepth
        elif isinstance(v, (list, tuple, set)):
            # Check if any direct element of these containers is a dict,
            # if yes, count the depth as 2 (root + 1)
            # but do not recurse into those dicts.
            if any(isinstance(item, dict) for item in v):
                max_subdepth = max(max_subdepth, 1)
    return 1 + max_subdepth



