def smallest_missing(arr, start, end):
    if start > end:
        return arr[start] if start < len(arr) else 0
    base = arr[start]
    left, right = start, end
    while left <= right:
        mid = (left + right) // 2
        expected = base + (mid - start)
        if arr[mid] == expected:
            left = mid + 1
        else:
            right = mid - 1
    return base + (left - start)



