def find_Max(array, low, high):
    # If subarray is empty or invalid, return None or raise error; here assume valid input
    # If subarray has one element, return it
    if low == high:
        return array[low]

    # If subarray is sorted ascending with no rotation, max is at high
    if array[low] < array[high]:
        return array[high]

    start, end = low, high
    while start <= end:
        mid = (start + end) // 2
        # Check if mid is pivot (max element)
        # max element is greater than next element (if any)
        if mid < high and array[mid] > array[mid + 1]:
            return array[mid]
        # max element is the element before pivot (if any)
        if mid > low and array[mid] < array[mid - 1]:
            return array[mid - 1]
        # Decide which side to search
        if array[mid] >= array[low]:
            # max is in right half
            start = mid + 1
        else:
            # max is in left half
            end = mid - 1
    # Fallback (should not reach here if input is valid rotated sorted array)
    return array[low]



