def str_to_tuple(s: str) -> tuple[int, ...]:
    if s == '':
        return ()
    # Check for strict format: integers separated by ', ' only, no extra spaces before commas
    parts = s.split(', ')
    if len(parts) == 1:
        # Single integer, ensure no commas or spaces around commas appear anywhere
        if ',' in s:
            # Comma present but split did not split, means spacing is wrong
            raise ValueError("Input string does not match strict format of integers separated by ', '")
        try:
            return (int(s),)
        except ValueError as e:
            raise ValueError("All elements must be valid integers") from e
    # Rebuild string from parts and compare to input to detect spacing errors
    if s != ', '.join(parts):
        raise ValueError("Input string does not match strict format of integers separated by ', '")
    # Also ensure no extra spaces around commas
    # Check that no part contains commas or spaces except allowed leading minus sign and digits
    for part in parts:
        if not part or part.strip() != part:
            raise ValueError("Input string does not match strict format of integers separated by ', '")
        if ',' in part:
            raise ValueError("Input string does not match strict format of integers separated by ', '")
    try:
        return tuple(int(p) for p in parts)
    except ValueError as e:
        raise ValueError("All elements must be valid integers") from e



