def lucky_num(n: int) -> list[int]:
    if n == 0:
        return []
    numbers = list(range(1, 10**6))  # Start with a large enough list
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            continue
        # If list got too small, extend it
        last = numbers[-1]
        numbers.extend(range(last + 1, last + 1 + 10**6))
    return numbers[:n]



