def dif_Square(n: int) -> bool:
    """
    Determine whether the given integer n can be expressed as the difference of squares of two integers.

    More formally, check if there exist integers a and b (where a and b can be any integers, including negative values, and a may be equal to b) such that:
        a² - b² = n

    Note:
    - Since a and b can be equal, dif_Square(0) should return True because 0 = a² - a² for any integer a.
    - The function takes a single integer parameter n.
    """
    # Using number theory:
    # a^2 - b^2 = (a+b)(a-b)
    # n = x * y, where x = a+b, y = a-b
    # a = (x + y)/2, b = (x - y)/2 must be integers
    # So x and y must have the same parity (both even or both odd)
    # Since x*y = n, n can be expressed as difference of squares iff n is NOT congruent to 2 mod 4.
    return n % 4 != 2



