def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)
    # If single digit, return the next smaller palindrome (which is just n-1 if >=1)
    if length == 1:
        return n - 1 if n > 0 else 0

    # Helper to check palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Generate palindrome by mirroring left side
    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            pal = left + left[:-1][::-1]
        else:
            pal = left + left[::-1]
        return int(pal)

    # Try to create a palindrome with the same length smaller than n
    # Step 1: Get the left half (and middle if odd)
    half_len = (length + 1) // 2
    left = s[:half_len]
    odd_length = (length % 2 != 0)

    # Step 2: Form palindrome from left
    pal = make_palindrome(left, odd_length)

    if pal >= n:
        # Need to decrement the left half and form palindrome again
        # Convert left to int, decrement, handle zero-padding
        left_num = int(left) - 1
        if left_num <= 0:
            # No smaller palindrome with the same number of digits
            # Return the largest palindrome with fewer digits
            return int('9' * (length - 1)) if length > 1 else 0
        left_str = str(left_num)
        # If length reduced due to decrement, pad with zeros on the left
        if len(left_str) < len(left):
            left_str = '0' * (len(left) - len(left_str)) + left_str
        pal = make_palindrome(left_str, odd_length)
        # If palindrome formed is still >= n, decrement more until smaller or fallback
        while pal >= n:
            left_num -= 1
            if left_num <= 0:
                return int('9' * (length - 1)) if length > 1 else 0
            left_str = str(left_num)
            if len(left_str) < len(left):
                left_str = '0' * (len(left) - len(left_str)) + left_str
            pal = make_palindrome(left_str, odd_length)
    else:
        # pal < n, but maybe pal == n if input is palindrome? Already handled above.
        pass

    if pal < n:
        return pal
    else:
        # Fallback
        return int('9' * (length - 1)) if length > 1 else 0



