def find_solution(a: int, b: int, n: int):
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return "No solution"
    if b == 0:
        # ax = n, y arbitrary, choose y=0
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return "No solution"
    if a == 0:
        # by = n, x arbitrary, choose x=0
        if n % b == 0:
            y = n // b
            return (0, y)
        return "No solution"

    # General case: try x from 0 upwards until a*x > n if a > 0 or no limit if a < 0
    # But since no domain restrictions, try x from 0 upwards until no solution possible.
    # To avoid infinite loop, we can reason:
    # For positive a and b, x max ~ n//a
    # For negative a or b, domain is unbounded, but we must still find first x≥0 with integer y.
    # So we can just try x from 0 up to a limit where no solution possible or break if no solution found in reasonable range.
    # Since no constraints, we can try x in range(0, abs(n) + abs(b) + abs(a) + 1000) as a safe bound.

    # But to be sure to cover negative and zero cases safely, just try from 0 up to some limit
    limit = 10**6  # large enough limit to find solution or conclude no solution

    for x in range(0, limit):
        remainder = n - a * x
        if b != 0 and remainder % b == 0:
            y = remainder // b
            return (x, y)
    return "No solution"



