def remove_column(data: list[list], n: int) -> list[list]:
    """
    Remove the column at index n from each row in the nested list data.

    Parameters:
    - data: a list of lists, where each inner list represents a row.
    - n: an integer representing the index of the column to remove.

    Returns:
    - A new list of lists, each with the nth element removed.

    Raises:
    - An error if n is out of range for any row in data.

    Examples:
    >>> remove_column([[1, 2, 3], [4, 5, 6]], 1)
    [[1, 3], [4, 6]]
    >>> remove_column([[1, 2], [3, 4]], 0)
    [[2], [4]]
    """
    result = []
    for row in data:
        if not (-len(row) <= n < len(row)):
            raise IndexError(f"Column index {n} out of range for row {row}")
        new_row = row[:n] + row[n+1:]
        result.append(new_row)
    return result



