def find_Max(arr: list, low: int, high: int):
    # If subarray is strictly ascending (no rotation), max is arr[high]
    if arr[low] < arr[high]:
        return arr[high]
    # Otherwise, binary search for max in rotated subarray
    left, right = low, high
    while left < right:
        mid = (left + right) // 2
        if arr[mid] > arr[right]:
            left = mid + 1
        else:
            right = mid
    # left is the index of the smallest element (rotation point)
    # Max is the element before left if left > low, else arr[high]
    if left == low:
        return arr[high]
    else:
        return arr[left - 1]



