import re

def capital_words_spaces(text: str) -> str:
    # Find all words starting with an uppercase letter, followed by non-whitespace chars
    # This extracts words including internal punctuation
    words = re.findall(r'\b[A-Z][^\s]*', text)
    result = []
    for w in words:
        # Remove trailing punctuation: any trailing chars that are not letter, digit, underscore, or hyphen/underscore allowed internally
        # Only strip trailing chars that are not in allowed set: letters, digits, underscores, hyphens
        # We preserve internal punctuation but remove trailing punctuation chars like .,!,? etc.
        stripped = re.sub(r'[^\w\-]+$', '', w)
        result.append(stripped)
    return ' '.join(result)



