def length_Of_Last_Word(s: str) -> int:
    words = s.rstrip().split()
    if not words:
        return 0
    last_word = words[-1]
    # Strip trailing punctuation characters that are not alphanumeric or internal punctuation
    # Trailing punctuation to ignore: any character not alnum or one of internal punctuations
    # Internal punctuation: apostrophes, hyphens, underscores, dots inside the word (counted)
    # trailing punctuation can be .,!? etc.
    # Remove trailing characters that are not alnum or internal punctuation (apostrophe, hyphen, underscore)
    # but inside the word they count, so only trailing ones removed.
    # Define trailing punctuation as characters not in [a-zA-Z0-9'_-]
    i = len(last_word)
    while i > 0 and not (last_word[i-1].isalnum() or last_word[i-1] in "'-_"):
        i -= 1
    trimmed = last_word[:i]
    return len(trimmed)



