def substract_elements(a, b):
    if type(a) != type(b):
        raise TypeError(f"Outer collections differ in type: {type(a)} vs {type(b)}")
    if len(a) != len(b):
        raise ValueError(f"Outer collections differ in length: {len(a)} vs {len(b)}")
    outer_type = type(a)
    inner_type = type(a[0]) if a else None
    for i in range(len(a)):
        if type(a[i]) != type(b[i]):
            raise TypeError(f"Inner collections differ in type at index {i}: {type(a[i])} vs {type(b[i])}")
        if len(a[i]) != len(b[i]):
            raise ValueError(f"Inner collections differ in length at index {i}: {len(a[i])} vs {len(b[i])}")
    result = []
    for i in range(len(a)):
        row_a = a[i]
        row_b = b[i]
        inner_type = type(row_a)
        new_row = inner_type(row_a[j] - row_b[j] for j in range(len(row_a)))
        result.append(new_row)
    return outer_type(result)



