def lucky_num(n: int) -> list[int]:
    # Start with a sufficiently large list of odd numbers including 1.
    # Use an upper bound to ensure at least n lucky numbers remain after sieving.
    # Since lucky numbers grow roughly faster than linear, a multiplier of 10 is safe.
    limit = 10 * n * 10  # arbitrary large to ensure enough lucky numbers
    numbers = [x for x in range(1, limit, 2)]

    idx = 1  # start with step = numbers[1] = 3
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list (1-based indexing)
        # So we remove numbers at indices: step-1, 2*step-1, 3*step-1, ...
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
        idx += 1
        if len(numbers) >= n and idx >= n:
            # If we already have more than n lucky numbers and processed enough steps, can stop early
            # But to be consistent with spec, continue until stable or no further removals
            pass

    return numbers[:n]



