def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    def is_all_nines(num_str):
        return all(ch == '9' for ch in num_str)

    # If all 9's, next palindrome is 10...01 with length+1 digits
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to build palindrome by mirroring left to right
    def make_palindrome(left, odd_length):
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    # Increment a numeric string and return it
    def increment_str(num_str):
        num = int(num_str) + 1
        return str(num)

    odd = (length % 2 != 0)
    mid = length // 2

    if odd:
        left = s[:mid+1]  # include middle
    else:
        left = s[:mid]

    # Construct palindrome from left half
    pal = make_palindrome(left, odd)

    if pal > n:
        return pal
    else:
        # Increment the left half and form palindrome again
        left_inc = increment_str(left)
        # Handle length increase due to increment (e.g. 99 -> 100)
        if len(left_inc) > len(left):
            # This means palindrome length increases by 1
            # For example, 999 -> 1001
            return int('1' + ('0' * (length - 1)) + '1')
        else:
            return make_palindrome(left_inc, odd)



