def find_solution(a: int, b: int, n: int):
    """
    Find non-negative integers x and y satisfying the equation a*x + b*y = n.

    Parameters:
    - a (int): The coefficient of x.
    - b (int): The coefficient of y.
    - n (int): The target integer value.

    Returns:
    - A tuple (x, y) of non-negative integers such that a*x + b*y = n, if such a solution exists.
    - The string 'No solution' if no such non-negative integer solution exists.

    Notes:
    - Both x and y must be integers greater than or equal to zero.
    - If multiple solutions exist, any one valid solution may be returned.

    Examples:
    >>> find_solution(3, 5, 11)
    (2, 1)
    >>> find_solution(2, 4, 3)
    'No solution'
    """
    if n < 0:
        return "No solution"

    max_x = n // a if a != 0 else 0
    for x in range(max_x + 1):
        rem = n - a * x
        if rem < 0:
            break
        if b == 0:
            if rem == 0:
                return (x, 0)
            else:
                continue
        if rem % b == 0:
            y = rem // b
            if y >= 0:
                return (x, y)
    return "No solution"



