def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 1:
        return m
    dp_prev = [1] * (m + 1)  # dp_prev[x] = count of sequences of length 1 starting with x, x in [1..m], index 0 unused
    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        suffix_sum = 0
        # We will compute suffix sums of dp_prev from the right to efficiently sum dp_prev[y] for y >= 2*x
        # Precompute suffix sums of dp_prev
        suffix_sums = [0] * (m + 2)  # extra element to avoid index error
        for i in range(m, 0, -1):
            suffix_sums[i] = suffix_sums[i + 1] + dp_prev[i]
        for x in range(1, m + 1):
            min_next = 2 * x
            if min_next <= m:
                dp_curr[x] = suffix_sums[min_next]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr
    return sum(dp_prev[1:])



