def smallest_missing(arr, left, right):
    if left > right:
        return 0
    while left <= right:
        mid = (left + right) // 2
        # Count of numbers <= mid - left subarray start index
        if arr[mid] < 0:
            left = mid + 1
        elif arr[mid] == mid - left:
            left = mid + 1
        elif arr[mid] > mid - left:
            right = mid - 1
        else:
            left = mid + 1
    return left - left  # left - original left index is the smallest missing



