from typing import List

def find_Max(arr: List[int], start: int, end: int) -> int:
    # If subarray has only one element
    if start == end:
        return arr[start]

    # If subarray is fully sorted (no rotation), max is at end
    if arr[start] < arr[end]:
        return arr[end]

    # Binary search for max in rotated sorted subarray
    left, right = start, end
    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than next element, mid is max
        if mid < end and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # If mid element is greater than left element,
        # max must be to the right of mid
        if arr[mid] >= arr[left]:
            left = mid + 1
        else:
            right = mid
    # If while loop ends, max is at left-1 or left, check safely
    # Because left can be at start or at end
    # We compare arr[left] and arr[left-1] if left > start
    if left > start and arr[left - 1] > arr[left]:
        return arr[left - 1]
    return arr[left]



