def capital_words_spaces(text: str) -> str:
    result = []
    i = 0
    n = len(text)

    while i < n:
        c = text[i]

        if c.isupper():
            # Collect consecutive uppercase letters
            start = i
            while i < n and text[i].isupper():
                i += 1
            # Check if next char exists and is lowercase -> this means the last uppercase letter is start of a capitalized word, not acronym
            if i < n and text[i].islower():
                # Acronym is all uppercase except the last uppercase letter which starts the capitalized word
                acronym_end = i - 1
                if acronym_end > start:
                    # Add acronym
                    if result:
                        result.append(' ')
                    result.append(text[start:acronym_end])
                elif acronym_end == start:
                    # Single uppercase letter before capitalized word is considered acronym part
                    if result:
                        result.append(' ')
                    result.append(text[start:acronym_end])

                # Now collect the capitalized word starting with one uppercase letter followed by lowercase letters
                word_start = acronym_end
                word_end = word_start + 1
                while word_end < n and text[word_end].islower():
                    word_end += 1
                if result and (acronym_end >= start):  # If acronym was appended, add space before word
                    result.append(' ')
                elif not result and (acronym_end == start):
                    # If no acronym before, no space needed before first word
                    pass
                else:
                    # If no acronym and not first word, add space
                    if result:
                        result.append(' ')
                result.append(text[word_start:word_end])
                i = word_end
            else:
                # No lowercase letter after uppercase sequence: treat all as acronym
                if result:
                    result.append(' ')
                result.append(text[start:i])
        else:
            # Collect lowercase or other chars until next uppercase letter followed by lowercase (new word start)
            start = i
            while i < n:
                if (
                    text[i].isupper()
                    and i + 1 < n
                    and text[i + 1].islower()
                ):
                    break
                i += 1
            chunk = text[start:i]
            if result and chunk:
                # Add space before chunk only if previous chunk ended with lowercase or acronym
                # But spec does not require adding spaces here, so no space added
                pass
            result.append(chunk)

    return ''.join(result)



