def substract_elements(first: tuple, second: tuple) -> tuple:
    min_outer_len = min(len(first), len(second))
    result = []
    for i in range(min_outer_len):
        inner_first = first[i]
        inner_second = second[i]
        # Check if inner elements are tuples of atomic numbers (not tuples)
        # If they contain tuples, return inner_first as is (no subtraction)
        if not (all(not isinstance(x, tuple) for x in inner_first) and all(not isinstance(x, tuple) for x in inner_second)):
            result.append(inner_first)
            continue
        min_inner_len = min(len(inner_first), len(inner_second))
        inner_result = tuple(inner_first[j] - inner_second[j] for j in range(min_inner_len))
        result.append(inner_result)
    return tuple(result)



