def lucky_num(n: int) -> list[int]:
    # Initial list: start with a length guess larger than n to ensure enough lucky numbers
    # The list will be repeatedly filtered by the sieve process until it has at least n lucky numbers.
    # Start with a list of natural numbers starting at 1.
    if n == 0:
        return []
    # We progressively increase the size of the list until we have enough lucky numbers.
    size = max(2 * n * n, 10)
    while True:
        numbers = list(range(1, size + 1))
        idx = 1  # start from the second element (index 1), since first is 1 and fixed
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
                break
            # Remove every step-th number from the current list, starting from index step-1 (0-based)
            # but skip the step-th number itself, so we remove items at positions: step-1, 2*step-1, 3*step-1, ...
            # Actually, the algorithm removes every step-th number (1-based indexing),
            # so in 0-based indexing, remove all items at indices i where (i+1) % step == 0.
            # But since the sieve uses the next remaining number to remove every step-th number,
            # and the counting restarts after each removal, the standard method is to remove items at multiples of step.
            # The standard implementation removes every step-th element in the list (1-based).
            # So to do this efficiently, we build a new list excluding those positions.
            numbers = [num for pos, num in enumerate(numbers, start=1) if pos % step != 0]
            idx += 1
        if len(numbers) >= n:
            return numbers[:n]
        size *= 2



