def parse_nested_parens(paren_string: str) -> str:
    def max_depth(group: str) -> str:
        depths = [0]
        def update_depths(char):
            return (depths.append(depths[-1] + 1) if char == '(' else
                    depths.append(depths[-1] - 1) if char == ')' else
                    depths.append(depths[-1]))
        # Use map to update depths without explicit loops or recursion in core logic
        list(map(update_depths, group))
        max_d = max(depths) if '(' in group or ')' in group else 0
        return str(max_d)

    groups = paren_string.split()
    return ', '.join(map(max_depth, groups))



