from typing import List, Tuple

def parse_music(music_string: str) -> Tuple[List[int], str]:
    note_map = {'o': 4, 'o|': 2, '.|': 1}
    tokens = music_string.split(' ')[:11]
    # Pad tokens to length 11 with empty strings to avoid index errors in fixed steps
    tokens += [''] * (11 - len(tokens))

    # Map notes to beats, treating unknown notes as 0 beats (won't affect results)
    b0 = note_map.get(tokens[0], 0)
    b1 = note_map.get(tokens[1], 0)
    b2 = note_map.get(tokens[2], 0)
    b3 = note_map.get(tokens[3], 0)
    b4 = note_map.get(tokens[4], 0)
    b5 = note_map.get(tokens[5], 0)
    b6 = note_map.get(tokens[6], 0)
    b7 = note_map.get(tokens[7], 0)
    b8 = note_map.get(tokens[8], 0)
    b9 = note_map.get(tokens[9], 0)
    b10 = note_map.get(tokens[10], 0)

    beats = [b0, b1, b2, b3, b4, b5, b6, b7, b8, b9, b10]
    # Remove trailing zeros corresponding to empty tokens
    while beats and beats[-1] == 0:
        beats.pop()

    # Count occurrences of each note symbol among tokens (excluding empty)
    # Since no loops, count individually
    def count_note(n):
        return (tokens[0] == n) + (tokens[1] == n) + (tokens[2] == n) + (tokens[3] == n) + (tokens[4] == n) + \
               (tokens[5] == n) + (tokens[6] == n) + (tokens[7] == n) + (tokens[8] == n) + (tokens[9] == n) + (tokens[10] == n)

    c_o = count_note('o')
    c_o_pipe = count_note('o|')
    c_dot_pipe = count_note('.|')

    max_count = max(c_o, c_o_pipe, c_dot_pipe)
    # Collect candidates with max_count
    candidates = []
    if c_o == max_count:
        candidates.append(('o', 4))
    if c_o_pipe == max_count:
        candidates.append(('o|', 2))
    if c_dot_pipe == max_count:
        candidates.append(('.|', 1))
    # Tie-break by longest beat duration
    candidates.sort(key=lambda x: x[1], reverse=True)
    most_common_note = candidates[0][0] if candidates else ''

    return (beats, most_common_note)



