def monotonic(l):
    if isinstance(l, list):
        # Check non-decreasing: all adjacent pairs satisfy l[i] <= l[i+1]
        non_decreasing = all(x <= y for x, y in zip(l, l[1:]))
        # Check non-increasing: all adjacent pairs satisfy l[i] >= l[i+1]
        non_increasing = all(x >= y for x, y in zip(l, l[1:]))
        if non_decreasing or non_increasing:
            return True, sum(l)
        else:
            return False
    elif isinstance(l, str):
        # If duplicates in string, return False
        if len(set(l)) != len(l):
            return False
        # Strictly increasing: all adjacent pairs l[i] < l[i+1]
        strictly_increasing = all(x < y for x, y in zip(l, l[1:]))
        # Strictly decreasing: all adjacent pairs l[i] > l[i+1]
        strictly_decreasing = all(x > y for x, y in zip(l, l[1:]))
        if strictly_increasing or strictly_decreasing:
            return True, l
        else:
            return False



