def total_match(lst1, lst2):
    def digit_count(n):
        return len(str(abs(n)))

    def total_digits(lst):
        return sum(digit_count(x) for x in lst)

    def total_length(lst):
        return sum(len(s) for s in lst)

    # Determine types of lists (empty lists default to int for convenience)
    type1 = int if not lst1 else type(lst1[0])
    type2 = int if not lst2 else type(lst2[0])

    # Compute totals according to type scenarios
    if type1 is int and type2 is int:
        total1 = total_digits(lst1)
        total2 = total_digits(lst2)
    elif type1 is str and type2 is str:
        total1 = total_length(lst1)
        total2 = total_length(lst2)
    else:  # Mixed types
        if type1 is int:
            total1 = total_digits(lst1)
            total2 = total_length(lst2)
        else:
            total1 = total_length(lst1)
            total2 = total_digits(lst2)

    if total1 <= total2:
        return lst1
    else:
        return lst2



