def maximum(arr, k):
    if k == 0:
        return []
    # Use a min-heap of size k to track the largest k elements
    heap = []
    for x in arr:
        if len(heap) < k:
            # Insert element preserving heap property manually
            heap.append(x)
            # Bubble up
            i = len(heap) - 1
            while i > 0:
                parent = (i - 1) // 2
                if heap[parent] <= heap[i]:
                    break
                heap[parent], heap[i] = heap[i], heap[parent]
                i = parent
        else:
            # If current element > min element (heap[0]), replace and bubble down
            if x > heap[0]:
                heap[0] = x
                i = 0
                n = len(heap)
                while True:
                    left = 2 * i + 1
                    right = 2 * i + 2
                    smallest = i
                    if left < n and heap[left] < heap[smallest]:
                        smallest = left
                    if right < n and heap[right] < heap[smallest]:
                        smallest = right
                    if smallest == i:
                        break
                    heap[i], heap[smallest] = heap[smallest], heap[i]
                    i = smallest
    # Heap now contains k largest elements, but not sorted
    # Sort them with insertion sort ascending
    for j in range(1, len(heap)):
        key = heap[j]
        i = j - 1
        while i >= 0 and heap[i] > key:
            heap[i + 1] = heap[i]
            i -= 1
        heap[i + 1] = key
    return heap



