from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Given a string containing multiple groups of balanced parentheses separated by spaces, 
    compute the maximum depth of nested parentheses for each group.

    Each group consists solely of balanced parentheses (i.e., every opening parenthesis '(' 
    has a corresponding closing parenthesis ')'). The input guarantees that all groups are balanced.

    For each group, the function returns an integer representing the deepest level of nesting.

    Examples:
    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    if not paren_string.strip():
        return []
    groups = paren_string.split()
    depths = []
    for group in groups:
        current_depth = 0
        max_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1
        depths.append(max_depth)
    return depths



