def search(lst):
    '''
    Given a non-empty list of positive integers, return the greatest integer from the list that satisfies the following condition:
    its frequency in the list (the number of times it appears) is greater than or equal to the integer's own value.
    If no such integer exists, return -1.

    Parameters:
        lst (list of int): A non-empty list of positive integers.

    Returns:
        int: The greatest integer in the list whose frequency is at least equal to its value, or -1 if none exists.

    Examples:
        search([4, 1, 2, 2, 3, 1]) == 2
        search([1, 2, 2, 3, 3, 3, 4, 4, 4]) == 3
        search([5, 5, 4, 4, 4]) == -1
    '''
    from collections import Counter
    freq = Counter(lst)
    candidates = [x for x in freq if freq[x] >= x]
    return max(candidates) if candidates else -1



