def move_one_ball(arr):
    """
    Given an array 'arr' of N unique integers, determine whether it is possible to obtain a sorted array in non-decreasing order by performing any number of right shift operations (including zero shifts) on the array.

    A right shift operation consists of moving every element of the array one position to the right, with the last element wrapping around to the first position (index 0).

    Return True if the array is already sorted in non-decreasing order or can be made sorted by performing some number of right shifts. Otherwise, return False.

    If the array is empty, return True.

    Examples:
    move_one_ball([3, 4, 5, 1, 2]) ==> True
    Explanation: By performing 2 right shift operations, the array becomes [1, 2, 3, 4, 5], which is sorted.

    move_one_ball([3, 5, 4, 1, 2]) ==> False
    Explanation: No number of right shifts can produce a sorted array.

    move_one_ball([1, 2, 3, 4, 5]) ==> True
    Explanation: The array is already sorted, so zero shifts suffice.
    """
    if not arr:
        return True

    n = len(arr)

    # Check if the array is already sorted (zero shifts)
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # The array can be shifted right k times to get sorted if and only if
    # the array is a rotation of a sorted array.
    # Since right shift by k is equivalent to left shift by n-k,
    # we can check if the array is sorted after some rotation.

    # For unique elements, a rotated sorted array has exactly one place where arr[i] > arr[i+1].
    # Find such positions; if more than one, return False.
    # Then check if rotating arr to start from arr[i+1] gives a sorted array.

    count_breaks = 0
    break_index = -1
    for i in range(n):
        if arr[i] > arr[(i+1) % n]:
            count_breaks += 1
            break_index = (i + 1) % n
            if count_breaks > 1:
                return False

    if count_breaks == 0:
        # Already sorted (should have returned True earlier)
        return True

    # Rotate the array so that arr[break_index] becomes the first element
    rotated = arr[break_index:] + arr[:break_index]

    # Check if rotated array is sorted
    return all(rotated[i] <= rotated[i+1] for i in range(n-1))



