def maximum(arr, k):
    """
    Given an array arr of integers and a non-negative integer k, return a sorted list 
    of length exactly k containing the maximum k numbers from arr.

    If multiple elements share the value of the k-th largest number, include only as many 
    of those duplicates as needed to reach exactly k elements (choosing arbitrarily if necessary).

    Parameters:
        arr (List[int]): List of integers, length between 1 and 1000 inclusive.
        k (int): Non-negative integer, 0 <= k <= len(arr).

    Returns:
        List[int]: Sorted list of length k containing the maximum k numbers from arr.

    Examples:

        Input: arr = [-3, -4, 5], k = 3
        Output: [-4, -3, 5]

        Input: arr = [4, -4, 4], k = 2
        Output: [4, 4]

        Input: arr = [-3, 2, 1, 2, -1, -2, 1], k = 1
        Output: [2]

        Input: arr = [1, 2, 3], k = 0
        Output: []
    """
    if k == 0:
        return []
    sorted_arr = sorted(arr)
    threshold = sorted_arr[-k]
    result = []
    count_threshold = 0
    count_threshold_max = arr.count(threshold)
    for x in reversed(sorted_arr):
        if x > threshold:
            result.append(x)
        elif x == threshold and count_threshold < count_threshold_max:
            result.append(x)
            count_threshold += 1
        if len(result) == k:
            break
    return sorted(result)



