def solve(s):
    letters = [c for c in s if c.isalpha()]
    if not letters:
        return s[::-1]
    # Check if all letters are caseless: c.upper() == c.lower() == c
    if all(c.upper() == c.lower() == c for c in letters):
        return s
    result_chars = []
    for c in s:
        if c.isalpha():
            upper = c.upper()
            lower = c.lower()
            if upper != lower:
                # Reverse case
                if c.islower():
                    result_chars.append(upper)
                else:
                    result_chars.append(lower)
            else:
                # Caseless letter, leave unchanged
                result_chars.append(c)
        else:
            # Non-letter, leave unchanged
            result_chars.append(c)
    return ''.join(result_chars)



