from typing import List

def parse_music(music_string: str) -> List[int]:
    """
    Parse a string of musical notes in a special ASCII format and return a list of integers representing the duration in beats of each note.

    The input string consists of note symbols separated by spaces. Each note symbol corresponds to a single note with a specific duration:
      - 'o'  : whole note, lasts 4 beats
      - 'o|' : half note, lasts 2 beats
      - '.|' : quarter note, lasts 1 beat

    Notes are always separated by spaces; the input will never have concatenated notes without spaces.

    If the input contains any note symbol not listed above, the function should raise an error.

    Example:
    >>> parse_music('o o| .| o| o| .| .| .| .| o o')
    [4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4]
    """
    note_map = {'o':4, 'o|':2, '.|':1}
    notes = music_string.split()
    result = []
    for note in notes:
        if note not in note_map:
            raise ValueError(f"Invalid note symbol: {note}")
        result.append(note_map[note])
    return result



