def maximum(arr, k):
    if k == 0:
        return []
    from collections import Counter
    count_arr = Counter(arr)
    sorted_desc = sorted(arr, reverse=True)
    kth_value = sorted_desc[k-1]
    result = []
    count_result = Counter()
    for val in sorted_desc:
        if len(result) == k:
            break
        if val == kth_value:
            need = k - len(result)
            can_take = count_arr[val] - count_result[val]
            take = min(need, can_take)
            result.extend([val]*take)
            count_result[val] += take
        else:
            if count_result[val] < count_arr[val]:
                result.append(val)
                count_result[val] += 1
    result.sort()
    return result



