def monotonic(l: list) -> bool:
    """
    Return True if the list elements are strictly monotonic (strictly increasing or strictly decreasing),
    or constant (all elements equal); otherwise, return False.

    A list is considered strictly monotonic if each element is either strictly greater than the previous one
    (strictly increasing) or strictly less than the previous one (strictly decreasing).
    Lists with all equal elements are also considered monotonic.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([2, 2, 2])
    True
    """
    if len(l) < 2:
        return True

    increasing = all(x <= y for x, y in zip(l, l[1:]))
    decreasing = all(x >= y for x, y in zip(l, l[1:]))

    return increasing or decreasing



