def monotonic(l: list):
    """
    Return True if the elements of the list are monotonic, i.e., entirely non-increasing or entirely non-decreasing.

    A list is considered monotonic if for every pair of consecutive elements, the sequence never strictly increases and then decreases,
    nor strictly decreases and then increases. Non-strict inequalities are used, so equal consecutive elements are allowed.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 2, 2, 3])
    True
    """
    if not l or len(l) == 1:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(len(l) - 1):
        if l[i] > l[i + 1]:
            non_decreasing = False
        if l[i] < l[i + 1]:
            non_increasing = False
        if not non_decreasing and not non_increasing:
            return False
    return True



