def anti_shuffle(s):
    import re
    # Split the string into a list of tokens (words and spaces)
    tokens = re.findall(r'\S+|\s+', s)
    result = []
    for token in tokens:
        if token.isspace():
            # Preserve spaces exactly
            result.append(token)
        else:
            # Sort characters in the word (including punctuation) by ASCII ascending
            sorted_word = ''.join(sorted(token))
            result.append(sorted_word)
    return ''.join(result)



