def max_fill(grid, capacity):
    total_ops = 0
    import math
    for well in grid:
        # Find indices of first and last water unit
        try:
            first = well.index(1)
            last = len(well) - 1 - well[::-1].index(1)
        except ValueError:
            # No water units in this well
            continue
        # Count water units in the segment from first to last inclusive
        units = sum(well[first:last+1])
        if units == 0:
            continue
        # Calculate lowering operations as ceiling(units / capacity)
        ops = math.ceil(units / capacity)
        total_ops += ops
    return total_ops



