def decode_shift(s: str):
    """
    Decodes a string previously encoded by `encode_shift` by shifting each lowercase letter backward by 5 positions in the alphabet, wrapping around from 'a' to 'z' as needed. All other characters (including uppercase letters, digits, punctuation, and whitespace) are left unchanged.

    For example:
    - decode_shift("mjqqt") returns "hello"
    - decode_shift("mjqqt!") returns "hello!" (exclamation mark unchanged)
    """
    result = []
    for c in s:
        if 'a' <= c <= 'z':
            shifted = (ord(c) - ord('a') - 5) % 26 + ord('a')
            result.append(chr(shifted))
        else:
            result.append(c)
    return ''.join(result)



