def circular_shift(item, amount):
    # Convert non-sequence types to string for uniform handling
    if not hasattr(item, '__len__') or not hasattr(item, '__getitem__'):
        item = str(item)
    length = len(item)
    if amount > length:
        reversed_seq = item[::-1]
    else:
        reversed_seq = item[-amount:] + item[:-amount] if amount != 0 else item
    if isinstance(item, str):
        return reversed_seq
    elif isinstance(item, tuple):
        return tuple(reversed_seq)
    elif isinstance(item, list):
        return list(reversed_seq)
    else:
        # For other sequence types, try to preserve type using type constructor
        try:
            return type(item)(reversed_seq)
        except Exception:
            return reversed_seq



