from collections import Counter

def search(items):
    '''
    Given a non-empty sequence (such as a list or tuple) of positive integers, return the largest integer value v such that the frequency of v in the sequence is greater than or equal to v (frequency >= v).

    The frequency of a value is the number of times it appears in the input sequence.

    If no such value exists, return -1.

    Examples:
        search([4, 1, 2, 2, 3, 1]) == 2
        search([1, 2, 2, 3, 3, 3, 4, 4, 4]) == 3
        search([5, 5, 4, 4, 4]) == -1
        search([2, 2]) == 2
    '''
    freq = Counter(items)
    candidates = [v for v, c in freq.items() if c >= v]
    return max(candidates) if candidates else -1



