def decode_shift(s: str):
    """
    Takes as input a string encoded with the encode_shift function, which shifts every lowercase letter forward by 5 positions in the alphabet (wrapping around from 'z' to 'a'). 
    This function returns the decoded string by shifting every lowercase alphabetical character backward by 5 positions (wrapping around from 'a' to 'z').

    Non-lowercase characters (including uppercase letters, digits, punctuation, spaces, etc.) are preserved unchanged in the output.

    Example:
    decode_shift("fgh") -> "abc"
    decode_shift("fgh!") -> "abc!"
    """
    result = []
    for c in s:
        if 'a' <= c <= 'z':
            shifted = chr((ord(c) - ord('a') - 5) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(c)
