from collections import Counter

def search(lst):
    '''
    Given a non-empty list of positive integers, return the greatest integer in the list whose frequency 
    (the number of times it appears in the list) is greater than or equal to the integer itself. 
    If no such integer exists, return -1.

    Examples:
    search([4, 1, 2, 2, 3, 1]) == 4
    search([1, 2, 2, 3, 3, 3, 4, 4, 4]) == 4
    search([5, 5, 4, 4, 4]) == 5
    '''
