def total_match(lst1, lst2):
    sum1 = sum(len(s) for s in lst1)
    sum2 = sum(len(s) for s in lst2)
    # Both empty lists -> return []
    if not lst1 and not lst2:
        return []
    # Both sums zero and one list is [] and other is [''] (or similar)
    if sum1 == 0 and sum2 == 0:
        if (not lst1 and lst2) or (lst1 and not lst2):
            # Return [] instead of ['']
            return []
        # Both have zero sum but neither is empty list, return lst1 as tie-break
        return lst1
    if sum1 < sum2:
        return lst1
    if sum2 < sum1:
        return lst2
    # Tie: return lst1
    return lst1



