def move_one_ball(arr):
    """
    Given an array 'arr' of N unique integers arr[0], arr[1], ..., arr[N-1], determine if it is possible to obtain a non-decreasingly sorted array by performing any number of right shift operations on the array.

    A right shift operation consists of moving every element one position to the right, with the last element wrapping around to the first position (index 0).

    Return True if the array can be transformed into a non-decreasingly sorted array by applying zero or more right shifts; otherwise, return False.

    If the array is empty, return True.

    Examples:

    move_one_ball([3, 4, 5, 1, 2]) == True
    Explanation: By performing 2 right shift operations, the array becomes [1, 2, 3, 4, 5], which is sorted in non-decreasing order.

    move_one_ball([3, 5, 4, 1, 2]) == False
    Explanation: No number of right shifts can arrange the array in non-decreasing order.
    """
    if not arr:
        return True
    n = len(arr)
    count_desc = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            count_desc += 1
            if count_desc > 1:
                return False
    return True



