def anti_shuffle(s):
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            space_start = i
            while i < n and s[i] == ' ':
                i += 1
            result.append(s[space_start:i])
        else:
            word_start = i
            while i < n and s[i] != ' ':
                i += 1
            word = s[word_start:i]
            sorted_word = ''.join(sorted(word))
            result.append(sorted_word)
    return ''.join(result)



