def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Count the number of "drops" where arr[i] > arr[i+1]
    drops = 0
    drop_index = -1
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            drops += 1
            drop_index = i
            if drops > 1:
                return False
    if drops == 0:
        # Already sorted non-decreasing
        return True
    # Exactly one drop found at drop_index, check if rotation is valid
    # Check boundary condition for rotation between arr[-1] and arr[0]
    if arr[-1] > arr[0]:
        return False
    return True



