def sum_squares(lst):
    """
    This function takes a list of integers and processes each element based on its index as follows:
    - If the index is a multiple of 3 (including zero), the element is squared.
    - If the index is a multiple of 4 but not a multiple of 3, the element is cubed.
    - If the index is neither a multiple of 3 nor 4, the element remains unchanged.

    Note: For indexes that are multiples of both 3 and 4 (e.g., index 0), only squaring is applied (squaring takes precedence over cubing).

    The function then returns the sum of all processed elements.

    Examples:
    For lst = [1, 2, 3] the output should be 6
    For lst = [] the output should be 0
    For lst = [-1, -5, 2, -1, -5] the output should be -126
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total



