            continue
        max_depth = 0
        current_depth = 0
        valid = True
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            else:  # ch == ')'
                current_depth -= 1
                if current_depth < 0:
