def triples_sum_to_zero(l: list):
    """
    triples_sum_to_zero takes a list of integers as input.
    It returns True if there exist three distinct elements anywhere in the list
    whose sum is exactly zero, and False otherwise.

    Distinct elements refer to elements with different values, not necessarily at different positions.

    Examples:
    >>> triples_sum_to_zero([1, -1, 0])
    True
    >>> triples_sum_to_zero([1, 2, 3])
    False
    >>> triples_sum_to_zero([0, 0, 0])
    True
    >>> triples_sum_to_zero([1, 2, -3, 4])
    True
    """
    distinct_values = sorted(set(l))
    n = len(distinct_values)
    if n < 3:
        return False
    for i in range(n - 2):
        a = distinct_values[i]
        start = i + 1
        end = n - 1
        while start < end:
            b = distinct_values[start]
            c = distinct_values[end]
            s = a + b + c
            if s == 0:
                return True
            elif s < 0:
                start += 1
            else:
                end -= 1
    return False



