def parse_music(notes: str) -> list[int]:
    """
    Parse a string representing musical notes and return a list of integers corresponding 
    to how many beats each note lasts.

    Each note symbol in the input string is either:
    - a single character 'o' representing a whole note (4 beats), or
    - two characters ending with '|' representing half and quarter notes:
      * 'o|' for a half note (2 beats)
      * '.|' for a quarter note (1 beat)

    The input string contains these note symbols concatenated without separators.
    The parsing should be done greedily, matching two-character symbols ('o|', '.|') first,
    then single-character symbols ('o').

    Examples:
    >>> parse_music("o.o|.|")
    [4, 4, 2, 1]

    >>> parse_music("o|o|o|")
    [2, 2, 2]

    >>> parse_music("o.o.o")
    [4, 4, 4]
    """
    result = []
    i = 0
    length = len(notes)
    while i < length:
        # Try matching two char note ending with '|'
        if i + 1 < length and notes[i + 1] == '|':
            note = notes[i:i+2]
            if note == 'o|':
                result.append(2)
            elif note == '.|':
                result.append(1)
            else:
                # According to spec, only 'o|', '.|' possible two-char notes ending with '|'
                # So no other case expected; skip or error?
                # Spec does not define error behavior; assume input is valid.
                pass
            i += 2
        else:
            # Single char note, must be 'o' => 4 beats
            if notes[i] == 'o':
                result.append(4)
            else:
                # Spec does not mention other single chars; assume valid input.
                pass
            i += 1
    return result



