def triples_sum_to_zero(l):
    """
    triples_sum_to_zero takes a list of integers and returns a boolean indicating whether there exist three distinct elements in the list whose sum is zero.

    The three elements must be distinct elements at different positions in the list (i.e., not the same element used multiple times).

    Returns:
        True if such a triple exists, False otherwise.
    """
    n = len(l)
    if n < 3:
        return False
    l.sort()
    for i in range(n - 2):
        # Skip duplicates for i
        if i > 0 and l[i] == l[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            s = l[i] + l[left] + l[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False



