def move_one_ball(arr):
    """
    Given an array 'arr', determine if it is possible to obtain a sorted array in non-decreasing order 
    by performing any number of circular right shift operations on the array. 
    A circular right shift operation moves the last element of the array to the front.

    Return True if it is possible to obtain a sorted array after zero or more such rotations; otherwise, return False.
    If the array is empty, return True.

    Examples:
    move_one_ball([3, 4, 5, 1, 2]) == True   # Rotating right twice results in [1, 2, 3, 4, 5]
    move_one_ball([3, 5, 4, 1, 2]) == False  # No number of rotations can sort the array
    """
    if not arr:
        return True

    n = len(arr)
    # Count how many times the sequence decreases (arr[i] > arr[i+1])
    drops = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            drops += 1
            if drops > 1:
                return False
    return True



