from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split(' ')
    result = []
    for group in groups:
        if not group or any(c not in '()' for c in group):
            result.append(0)
            continue
        depth = 0
        max_depth = 0
        balanced = True
        for c in group:
            if c == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            else:  # c == ')'
                depth -= 1
                if depth < 0:
                    balanced = False
                    break
        if balanced and depth == 0:
            result.append(max_depth)
        else:
            result.append(0)
    return result



