def fizz_buzz(n: int) -> int:
    """
    Count and return the total number of times the digit '7' appears in the decimal representation 
    of all integers less than n that are divisible by 11 or 13.

    Parameters:
    n (int): The upper bound (exclusive) for checking integers.

    Returns:
    int: The total count of digit '7's in all integers less than n divisible by 11 or 13.
    """
    count = 0
    for x in range(11, n):
        if x % 11 == 0 or x % 13 == 0:
            count += str(x).count('7')
    return count



