def order_by_points(nums):
    """
    Sort the given list of integers in ascending order based on the sum of the digits 
    of their absolute values. If multiple integers have the same digit sum, their 
    relative order should be the same as in the original list (i.e., the sort should be stable).

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [1, -1, 11, -11, -12]
    >>> order_by_points([]) == []
    """
    def digit_sum(x):
        return sum(int(d) for d in str(abs(x)))
    return sorted(nums, key=digit_sum)



